# An output of type Directory is the EOAP stage-out result: it is a STAC
# Collection, not an opaque directory reference.
:EOAPStageOutDirectoryToSTACCollection
    a sh:NodeShape ;
    sh:targetSubjectsOf cwl:output ;
    sh:rule [
        a sh:SPARQLRule ;
        sh:construct """
            PREFIX cwl: <https://w3id.org/cwl/cwl#>
            PREFIX ogcproc: <http://www.opengis.net/def/ogcapi/processes/>
            PREFIX dct: <http://purl.org/dc/terms/>
            PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

            CONSTRUCT {
                ?outputNode ogcproc:schemaType "object"^^<http://www.w3.org/2001/XMLSchema#string> ;
                    dct:format <https://www.iana.org/assignments/media-types/application/json> ;
                    rdfs:seeAlso <https://stacspec.org/#collection-spec>
            }
            WHERE {
                $this cwl:output ?outputNode .
                ?outputNode cwl:type cwl:Directory
            }
        """ ;
    ] ;
